/// The operations of the API, each a call through the transport.
class SpezadoApi {
  const SpezadoApi(this.transport);

  final Transport transport;

  /// The books of the workspace.
  Future<List<BooksSummary>> books() async => (await transport.json('GET', '/api/v1/books') as List<Object?>)
      .map((e) => BooksSummary.fromJson(e as Map<String, Object?>))
      .toList();

  /// Sets up books for a person.
  Future<BooksSummary> setUp({required SetUp body}) async =>
      BooksSummary.fromJson(await transport.json('POST', '/api/v1/books', json: body.toJson()) as Map<String, Object?>);

  /// The accounts to book on, by national number.
  Future<List<AccountView>> accounts({required String books, String? lang}) async => (await transport.json(
    'GET',
    '/api/v1/books/${Uri.encodeComponent(books)}/accounts',
    query: {'lang': lang},
  ) as List<Object?>).map((e) => AccountView.fromJson(e as Map<String, Object?>)).toList();

  /// The balances of the accounts at the end of a year, those that have one.
  Future<List<BalanceView>> balances({required String books, int? year, String? lang}) async => (await transport.json(
    'GET',
    '/api/v1/books/${Uri.encodeComponent(books)}/balances',
    query: {'year': year, 'lang': lang},
  ) as List<Object?>).map((e) => BalanceView.fromJson(e as Map<String, Object?>)).toList();

  /// Books every open entry that has a proposal, all or none.
  Future<Accepted> acceptAll({required String books}) async => Accepted.fromJson(
    await transport.json('POST', '/api/v1/books/${Uri.encodeComponent(books)}/bank/accept-all') as Map<String, Object?>,
  );

  /// The entries of bank statements not booked yet, each with a proposal where there is one.
  Future<List<OpenEntry>> openEntries({required String books}) async =>
      (await transport.json('GET', '/api/v1/books/${Uri.encodeComponent(books)}/bank/entries') as List<Object?>)
          .map((e) => OpenEntry.fromJson(e as Map<String, Object?>))
          .toList();

  /// Books an entry by its proposal.
  Future<Written> accept({required String books, required EntryRef body}) async => Written.fromJson(
    await transport.json('POST', '/api/v1/books/${Uri.encodeComponent(books)}/bank/entries/accept', json: body.toJson())
        as Map<String, Object?>,
  );

  /// Books an entry on an account with a tax code, its amount as the gross amount.
  Future<Written> bookEntry({required String books, required BookEntry body}) async => Written.fromJson(
    await transport.json('POST', '/api/v1/books/${Uri.encodeComponent(books)}/bank/entries/book', json: body.toJson())
        as Map<String, Object?>,
  );

  /// Fetches statements from the bank by FinTS – waits for the product registration of falkOSS, answers 501 until then.
  Future<void> fetch({required String books}) =>
      transport.none('POST', '/api/v1/books/${Uri.encodeComponent(books)}/bank/fetch');

  /// Reads a file of statements – camt.053, MT940 or a bank's CSV file – and records each statement.
  Future<Imported> import({required String books, String? name, String? iban, required Uint8List file}) async =>
      Imported.fromJson(
        await transport.json(
          'POST',
          '/api/v1/books/${Uri.encodeComponent(books)}/bank/statements',
          query: {'name': name, 'iban': iban},
          bytes: file,
        ) as Map<String, Object?>,
      );

  /// Books lines that balance.
  Future<Written> bookLines({required String books, required LinesBooking body}) async => Written.fromJson(
    await transport.json('POST', '/api/v1/books/${Uri.encodeComponent(books)}/bookings/lines', json: body.toJson())
        as Map<String, Object?>,
  );

  /// Books a gross amount on an account, split by its tax code, against the bank or the cash.
  Future<Written> bookSimple({required String books, required SimpleBooking body}) async => Written.fromJson(
    await transport.json('POST', '/api/v1/books/${Uri.encodeComponent(books)}/bookings/simple', json: body.toJson())
        as Map<String, Object?>,
  );

  /// Closes the books of their owner up to a date.
  Future<Written> close({required String books, required Close body}) async => Written.fromJson(
    await transport.json('POST', '/api/v1/books/${Uri.encodeComponent(books)}/closings', json: body.toJson())
        as Map<String, Object?>,
  );

  /// The customers, by name.
  Future<List<Customer>> customers({required String books}) async =>
      (await transport.json('GET', '/api/v1/books/${Uri.encodeComponent(books)}/customers') as List<Object?>)
          .map((e) => Customer.fromJson(e as Map<String, Object?>))
          .toList();

  /// Keeps a customer – new without an identity, else replacing the one with it.
  Future<Saved> saveCustomer({required String books, required Customer body}) async => Saved.fromJson(
    await transport.json('POST', '/api/v1/books/${Uri.encodeComponent(books)}/customers', json: body.toJson())
        as Map<String, Object?>,
  );

  /// The facts that move the owner's deadlines today: the state whose public holidays apply and whether VAT returns
  /// are extended for good.
  Future<Deadlines> deadlines({required String books}) async => Deadlines.fromJson(
    await transport.json('GET', '/api/v1/books/${Uri.encodeComponent(books)}/deadlines') as Map<String, Object?>,
  );

  /// Changes the facts that move the owner's deadlines from a date on; everything else stays as configured.
  Future<Deadlines> changeDeadlines({required String books, required Deadlines body}) async => Deadlines.fromJson(
    await transport.json('PUT', '/api/v1/books/${Uri.encodeComponent(books)}/deadlines', json: body.toJson())
        as Map<String, Object?>,
  );

  /// The documents recorded, newest first.
  Future<List<DocumentView>> documents({required String books}) async =>
      (await transport.json('GET', '/api/v1/books/${Uri.encodeComponent(books)}/documents') as List<Object?>)
          .map((e) => DocumentView.fromJson(e as Map<String, Object?>))
          .toList();

  /// Reads a file – an e-invoice (XRechnung, ZUGFeRD), a PDF, a photo – as a document, with a proposal for an e-invoice.
  /// Nothing is recorded until it is named in `documents/pending/{pending}` within the hour.
  Future<ReadDocument> readDocument({
    required String books,
    String? name,
    String? side,
    String? payment,
    required Uint8List file,
  }) async => ReadDocument.fromJson(
    await transport.json(
      'POST',
      '/api/v1/books/${Uri.encodeComponent(books)}/documents',
      query: {'name': name, 'side': side, 'payment': payment},
      bytes: file,
    ) as Map<String, Object?>,
  );

  /// Records a document read – alone, or with its proposal, dated and worded as given.
  Future<Written> record({required String books, required String pending, required Record body}) async =>
      Written.fromJson(
        await transport.json(
          'POST',
          '/api/v1/books/${Uri.encodeComponent(books)}/documents/pending/${Uri.encodeComponent(pending)}',
          json: body.toJson(),
        ) as Map<String, Object?>,
      );

  /// The original of a document, byte for byte.
  Future<Uint8List> original({required String books, required String document}) => transport.bytes(
    'GET',
    '/api/v1/books/${Uri.encodeComponent(books)}/documents/${Uri.encodeComponent(document)}/original',
  );

  /// The data transfer of the GoBD (Z3) for a period, as a ZIP file: `index.xml` and its CSV files.
  Future<Uint8List> gobd({required String books, required String from, required String to}) =>
      transport.bytes('GET', '/api/v1/books/${Uri.encodeComponent(books)}/gobd', query: {'from': from, 'to': to});

  /// Writes an invoice as XRechnung and records it; with double entry, its receivable is booked.
  Future<Issued> issue({required String books, required NewInvoice body}) async => Issued.fromJson(
    await transport.json('POST', '/api/v1/books/${Uri.encodeComponent(books)}/invoices', json: body.toJson())
        as Map<String, Object?>,
  );

  /// The number the next invoice of a year gets.
  Future<NextNumber> nextNumber({required String books, int? year}) async => NextNumber.fromJson(
    await transport.json(
      'GET',
      '/api/v1/books/${Uri.encodeComponent(books)}/invoices/next-number',
      query: {'year': year},
    ) as Map<String, Object?>,
  );

  /// The seller's details on invoices; null before they are given.
  Future<InvoiceProfile?> profile({required String books}) async =>
      await transport.json('GET', '/api/v1/books/${Uri.encodeComponent(books)}/invoicing/profile') == null
      ? null
      : InvoiceProfile.fromJson(
          await transport.json('GET', '/api/v1/books/${Uri.encodeComponent(books)}/invoicing/profile')
              as Map<String, Object?>,
        );

  /// Keeps the seller's details on invoices.
  Future<InvoiceProfile> setProfile({required String books, required InvoiceProfile body}) async =>
      InvoiceProfile.fromJson(
        await transport.json(
          'PUT',
          '/api/v1/books/${Uri.encodeComponent(books)}/invoicing/profile',
          json: body.toJson(),
        ) as Map<String, Object?>,
      );

  /// The bookings of a year, by date.
  Future<List<JournalEntry>> journal({required String books, int? year, String? lang}) async => (await transport.json(
    'GET',
    '/api/v1/books/${Uri.encodeComponent(books)}/journal',
    query: {'year': year, 'lang': lang},
  ) as List<Object?>).map((e) => JournalEntry.fromJson(e as Map<String, Object?>)).toList();

  /// The first day of the books and the opening balances booked.
  Future<OpeningView> opening({required String books, String? lang}) async => OpeningView.fromJson(
    await transport.json('GET', '/api/v1/books/${Uri.encodeComponent(books)}/opening', query: {'lang': lang})
        as Map<String, Object?>,
  );

  /// Books opening balances, once, against the opening balance sheet – they count in balances, in no result.
  Future<Written> bookOpening({required String books, required Opening body}) async => Written.fromJson(
    await transport.json('POST', '/api/v1/books/${Uri.encodeComponent(books)}/opening', json: body.toJson())
        as Map<String, Object?>,
  );

  /// The books at a glance, for a year.
  Future<Overview> overview({required String books, int? year, String? lang}) async => Overview.fromJson(
    await transport.json(
      'GET',
      '/api/v1/books/${Uri.encodeComponent(books)}/overview',
      query: {'year': year, 'lang': lang},
    ) as Map<String, Object?>,
  );

  /// The reports of a year: the advance VAT returns with their deadlines, the annual ones.
  Future<List<ReportItem>> reports({required String books, int? year, String? lang}) async => (await transport.json(
    'GET',
    '/api/v1/books/${Uri.encodeComponent(books)}/reports',
    query: {'year': year, 'lang': lang},
  ) as List<Object?>).map((e) => ReportItem.fromJson(e as Map<String, Object?>)).toList();

  /// The figures of a report for a period – a draft until tax advisers have reviewed its mapping.
  Future<Figures> report({
    required String books,
    required String report,
    required String from,
    required String to,
    String? lang,
  }) async => Figures.fromJson(
    await transport.json(
      'GET',
      '/api/v1/books/${Uri.encodeComponent(books)}/reports/${Uri.encodeComponent(report)}',
      query: {'from': from, 'to': to, 'lang': lang},
    ) as Map<String, Object?>,
  );

  /// Reverses a booking.
  Future<Written> reverse({required String books, required Reversal body}) async => Written.fromJson(
    await transport.json('POST', '/api/v1/books/${Uri.encodeComponent(books)}/reversals', json: body.toJson())
        as Map<String, Object?>,
  );

  /// What needs review, each issue in a sentence of the language asked for.
  Future<List<String>> review({required String books, String? lang}) async => (await transport.json(
    'GET',
    '/api/v1/books/${Uri.encodeComponent(books)}/review',
    query: {'lang': lang},
  ) as List<Object?>).map((e) => e as String).toList();

  /// The tax codes to choose from.
  Future<List<TaxCodeView>> taxCodes({required String books, String? lang}) async => (await transport.json(
    'GET',
    '/api/v1/books/${Uri.encodeComponent(books)}/tax-codes',
    query: {'lang': lang},
  ) as List<Object?>).map((e) => TaxCodeView.fromJson(e as Map<String, Object?>)).toList();

  /// The devices paired.
  Future<List<Device>> devices() async => (await transport.json('GET', '/api/v1/devices') as List<Object?>)
      .map((e) => Device.fromJson(e as Map<String, Object?>))
      .toList();

  /// Revokes a device's token.
  Future<void> revoke({required String device}) =>
      transport.none('DELETE', '/api/v1/devices/${Uri.encodeComponent(device)}');

  /// Pairs a device with the code `spezado serve` shows; returns its token, once.
  Future<Paired> pair({required PairRequest body}) async =>
      Paired.fromJson(await transport.json('POST', '/api/v1/pair', json: body.toJson()) as Map<String, Object?>);

  /// The states whose public holidays can move deadlines.
  Future<List<RegionView>> regions({String? lang}) async =>
      (await transport.json('GET', '/api/v1/regions', query: {'lang': lang}) as List<Object?>)
          .map((e) => RegionView.fromJson(e as Map<String, Object?>))
          .toList();
}
